(function(){
'use strict';
const M={
fr:{ey:'ÉTAPE 1 · DOSSIER AVANT RÈGLEMENT',pay:'AUCUN PAIEMENT MAINTENANT',payText:'Envoyez d’abord vos renseignements. DIGIYLYFE contrôle et valide votre dossier humainement. Le règlement de la fiche n’est demandé qu’après cette validation.',send:'ENVOYER MON DOSSIER POUR VALIDATION →',ready:'Dossier prêt à être envoyé. Aucun règlement ni preuve de paiement n’est demandé à cette étape.',done:'Dossier reçu. DIGIYLYFE va le valider avant tout règlement.'},
en:{ey:'STEP 1 · FILE BEFORE PAYMENT',pay:'NO PAYMENT NOW',payText:'Send your information first. DIGIYLYFE reviews and validates your file. Payment for the professional profile is requested only after validation.',send:'SEND MY FILE FOR VALIDATION →',ready:'Your file is ready to send. No payment or payment proof is required at this stage.',done:'File received. DIGIYLYFE will validate it before any payment.'},
es:{ey:'PASO 1 · EXPEDIENTE ANTES DEL PAGO',pay:'NINGÚN PAGO AHORA',payText:'Envíe primero sus datos. DIGIYLYFE revisa y valida su expediente. El pago de la ficha solo se solicita después de la validación.',send:'ENVIAR MI EXPEDIENTE PARA VALIDACIÓN →',ready:'Expediente listo. No se solicita pago ni comprobante en esta etapa.',done:'Expediente recibido. DIGIYLYFE lo validará antes de cualquier pago.'},
pt:{ey:'ETAPA 1 · DOSSIER ANTES DO PAGAMENTO',pay:'NENHUM PAGAMENTO AGORA',payText:'Envie primeiro os seus dados. A DIGIYLYFE analisa e valida o dossier. O pagamento da ficha só é pedido após a validação.',send:'ENVIAR O MEU DOSSIER PARA VALIDAÇÃO →',ready:'Dossier pronto. Nenhum pagamento ou comprovativo é exigido nesta etapa.',done:'Dossier recebido. A DIGIYLYFE irá validá-lo antes de qualquer pagamento.'},
it:{ey:'FASE 1 · DOSSIER PRIMA DEL PAGAMENTO',pay:'NESSUN PAGAMENTO ORA',payText:'Invia prima i tuoi dati. DIGIYLYFE controlla e convalida il dossier. Il pagamento della scheda viene richiesto solo dopo la convalida.',send:'INVIA IL DOSSIER PER LA CONVALIDA →',ready:'Dossier pronto. In questa fase non è richiesto alcun pagamento o prova di pagamento.',done:'Dossier ricevuto. DIGIYLYFE lo convaliderà prima di qualsiasi pagamento.'},
de:{ey:'SCHRITT 1 · UNTERLAGEN VOR ZAHLUNG',pay:'JETZT KEINE ZAHLUNG',payText:'Senden Sie zuerst Ihre Angaben. DIGIYLYFE prüft und bestätigt Ihre Unterlagen. Die Zahlung für das Profi-Profil erfolgt erst nach dieser Prüfung.',send:'UNTERLAGEN ZUR PRÜFUNG SENDEN →',ready:'Unterlagen bereit. In diesem Schritt sind weder Zahlung noch Zahlungsnachweis erforderlich.',done:'Unterlagen erhalten. DIGIYLYFE prüft sie vor jeder Zahlung.'},
nl:{ey:'STAP 1 · DOSSIER VÓÓR BETALING',pay:'NU GEEN BETALING',payText:'Stuur eerst uw gegevens. DIGIYLYFE controleert en valideert het dossier. Betaling voor het professionele profiel wordt pas na validatie gevraagd.',send:'MIJN DOSSIER TER VALIDATIE VERSTUREN →',ready:'Dossier klaar. In deze stap is geen betaling of betalingsbewijs nodig.',done:'Dossier ontvangen. DIGIYLYFE valideert het vóór enige betaling.'},
ar:{ey:'الخطوة 1 · الملف قبل الدفع',pay:'لا دفع الآن',payText:'أرسل معلوماتك أولاً. تقوم DIGIYLYFE بمراجعة الملف والتحقق منه. لا يُطلب دفع ثمن الملف المهني إلا بعد التحقق.',send:'إرسال الملف للتحقق ←',ready:'الملف جاهز للإرسال. لا يُطلب دفع أو إثبات دفع في هذه المرحلة.',done:'تم استلام الملف. ستتحقق DIGIYLYFE منه قبل أي دفع.'}
};
function lang(){const l=(document.documentElement.lang||'fr').slice(0,2).toLowerCase();return M[l]?l:'fr'}
function apply(){const d=M[lang()],ey=document.getElementById('ey'),pt=document.getElementById('proofTitle'),pl=document.getElementById('proofLabel'),ph=document.getElementById('proofHelp'),btn=document.getElementById('submit'),st=document.getElementById('status');if(ey)ey.textContent=d.ey;if(pt)pt.textContent=d.pay;if(pl)pl.textContent=d.payText;if(ph)ph.textContent='';if(btn&&btn.style.display!=='none')btn.textContent=d.send;if(st&&!st.classList.contains('bad')){if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)){if(st.textContent!==d.ready)st.textContent=d.ready}}}
apply();
new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
document.querySelectorAll('#langs button').forEach(b=>b.addEventListener('click',()=>setTimeout(apply,0)));
const st=document.getElementById('status');if(st)new MutationObserver(()=>{const d=M[lang()];if(st.classList.contains('bad'))return;if(st.classList.contains('ok')){if(st.textContent!==d.done)st.textContent=d.done}else if(!/Envoi|Sending|Envío|Envio|Invio|Senden|Verzenden|إرسال/i.test(st.textContent)&&st.textContent!==d.ready){st.textContent=d.ready}}).observe(st,{childList:true,subtree:true,characterData:true,attributes:true,attributeFilter:['class']});
})();